% Builds a rectangular tile
% params: {tile-lenght}{tile-higt}{color}{shift}{rotate}
\newcommand{\myRecTile}[5]{
    \begin{scope}[shift={#4}, rotate=#5]
    	\coordinate (A) at (0, 0);
		\coordinate (B) at (0, #2);
	    \coordinate (C) at (#1, #2);
	    \coordinate (D) at (#1,0);

    	\tkzDrawPolygon[very thick, color=#3, fill = #3!15](A,B,C,D)	 
    \end{scope}  
}
% Builds a triangular tile
% params: {tile-lenght}{tile-higt}{color}{shift}{rotate}
\newcommand{\myTriagTile}[5]{
    \begin{scope}[shift={#4}]
    	\coordinate (A) at (0,0);
    		\pgfmathsetmacro{\xc}{#1*cos(-#5)+0*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1*sin(-#5)+0*cos(-#5)};
		\coordinate (B) at (\xc,\yc);
			\pgfmathsetmacro{\xc}{#1/2*cos(-#5)+#2*sin(-#5)};  
	    	\pgfmathsetmacro{\yc}{-#1/2*sin(-#5)+#2*cos(-#5)};
	    \coordinate (C) at (\xc,\yc);

    	\tkzDrawPolygon[very thick, color=#3, fill = #3!15](A,B,C)	 

    \end{scope}  
}
% Builds a net
% params: {color}
\newcommand{\myTrigPrismNet}[1]{

	\def\a{3}
	\def\h{4}

	\myTriagTile{\a}{\a*0.866}{#1}{(0,\h)}{0};
	\myRecTile{\a}{\h}{#1}{(0,0)}{0};
	\myRecTile{\a}{\h}{#1}{(\a,0)}{0};
	\myRecTile{\a}{\h}{#1}{(2*\a,0)}{0};
	\myTriagTile{\a}{\a*0.866}{#1}{(3*\a,0)}{180};
	\node[] at (1.5,4.75) {$8\,\text{mm}^2$};
	\node[] at (1.5,2) {$30\,\text{mm}^2$};

}

